def _format_evaluation(value) -> str:
    if isinstance(value, bool):
        return 'true' if value else 'false'
    text = str(value).strip()
    if text.lower() in {'true', 'false'}:
        return text.lower()
    return text


def _copy_raw_payload(raw: Path, public: Path) -> None:
    for item in raw.iterdir():
        if item.name in {'discovery_tasks.json', 'data_description.json'}:
            continue
        dst = public / item.name
        if item.is_dir():
            shutil.copytree(item, dst, dirs_exist_ok=True)
        else:
            shutil.copy2(item, dst)


def _write_json(path: Path, payload: dict) -> None:
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')


def prepare(raw: Path, public: Path, private: Path):
    public.mkdir(parents=True, exist_ok=True)
    private.mkdir(parents=True, exist_ok=True)

    _copy_raw_payload(raw, public)
    _write_json(public / 'data_description.json', PUBLIC_DATA_DESCRIPTION)
    _write_json(public / 'discovery_tasks.json', PUBLIC_TASK_SPEC)
    _write_json(private / 'task_metadata.json', PRIVATE_TASK_SPEC)

    pd.DataFrame({'id': [GLOBAL_TASK_ID], 'answer': ['@answer[your_answer_here]']}).to_csv(
        public / 'sample_submission.csv', index=False
    )
    pd.DataFrame({'id': [GLOBAL_TASK_ID], 'answer': [f"@answer[{_format_evaluation(EVALUATION)}]"]}).to_csv(
        private / 'answer.csv', index=False
    )
